function inheritance(s,id){const o=s.origin,r=[];
if(id===stay[0]||id===mobile[0])r.push(o.demo?'本次为独立试玩。前情采用'+(o.source==='已完成第一部的实际选择'?'你已完成第一部的选择，路线按这次试玩指定':'一组示例选择')+'。从第一部结局进入续篇可沿用那一轮的实际选择。':'一个月前留下的物品和约定，你都记在寄存簿里。今天翻开，还能看到那几张熟悉的交接单。');
if(['stay_letters','mobile_market'].includes(id))r.push(o.brew==='repair'?'Brew 得知你在核对维修去向，找来换新手时留下的收条。纸边卷了，它用杯底压平，又问会不会遮住字。收条上留着当时接收旧手的单位和白港批次。你征得它同意，拍下型号和编号。\n“原件我还得留着。”Brew 说，“以后可能要用。”\n你把纸交还，它仔细折好，放回提袋。':'Brew 找出那天下午练新手的录音，问你要不要听。杯子碰到柜台的声音过后，是你提醒它别急、先站稳的声音。\n“当时怕回家又忘了怎么练，就留下了。”它说，“你听这儿，我还问是不是碰巧。”\n你听见它在录音里笑了一声。Brew 问你能不能也留一份，免得下次又到处找，你说可以，和它一起存好副本。');
if(['stay_witness','mobile_shelter'].includes(id))r.push(o.seven==='shop'?'Seven 从自己那只盒子里翻出原始货签，举到通信镜头前。你请它把手指挪一点，露出底下的签收人。\n“不是宣传册上那位。”它说，“我送过这一班，发货地址还在。”\n你将地址抄下，Seven 又读了一遍，确认没有漏掉楼号。':'Seven 去了当初替它代收的工坊。负责人找到签收副本，让它带来给你们看。纸上没有完整的发货地址，值班交接栏却还清楚。\n“那天是这一位。”Seven 指着签名，“工坊说能替我们问问，他还记不记得车往哪边走。”\n你记下名字，等对方回话。');
if(['stay_accident','mobile_escape'].includes(id))r.push(o.mara==='relay'?'Mara 发来消息，说当初的卖家愿意和店里直接联系。她仍只帮忙转这一次，后面的事让你们自己谈。你回了谢谢，随后收到卖家发来的旧售后单。几张纸列着整机编号和再次出售的日期，你将它们与已有记录并排放好。':'你沿着当初寻找 Mara 义肢旧使用者时联系过的工坊，查到一册公开零件目录。同一批旧型号在里面列成了许多散件，旁边标着进货日期。你请工坊帮着核对来源，先将这一页留存；关于这些型号的原使用者，目录里没有写。');
if(['stay_depart','mobile_approach'].includes(id))r.push(o.rivet==='loan'?'Rivet 发来工具的借还单，问你记不记得哪把扳手的锁扣得先抬起来。你找出对应的工具给它看。单子附着旧检修工具的维护记录，进厂后能用来核对用法。\n“回来一起清点。”它说，“小的最容易落下。”':'工坊收到消息，安排了一位熟悉现场的维修工到外围接应。Rivet 问清对方能等到什么时候，将时间报给你。\n“工具现在归他们用，今天也排着活。”它说，“这一段是他们腾出来的，别让人白等。”\n你把集合点和时间又核对一次，交给负责联络的人。');
return r.flatMap(t=>t.split('\n'));}
function inheritedClues(s,id){const o=s.origin;if(['stay_letters','mobile_market'].includes(id))return [{title:o.brew==='repair'?'Brew的旧维修收条':'Brew的新手练习录音',detail:o.brew==='repair'?'核对接收型号和白港批次，来自Brew主动提供的个人物品。':'保留你与Brew练习时的说话声，来自双方愿意留下的日常。'}];if(['stay_witness','mobile_shelter'].includes(id))return [{title:o.seven==='shop'?'Seven的原始货签':'工坊的签收副本',detail:o.seven==='shop'?'指向发货端，可追查接收地点。':'指向中转端，可寻找当班见证者。'}];if(['stay_accident','mobile_escape'].includes(id))return [{title:o.mara==='relay'?'卖家自愿提供的售后单':'公开零件目录',detail:o.mara==='relay'?'指向整机抹记忆翻卖，Mara不承担后续义务。':'指向拆解销售渠道，不需要传递Mara的身份资料。'}];if(['stay_depart','mobile_approach'].includes(id))return [{title:o.rivet==='loan'?'工具借还与维护记录':'新使用者的接应约定',detail:o.rivet==='loan'?'可以核对旧检修工具；借期和归还责任仍存在。':'援助来自新使用者的自愿，赠送不被撤销。'}];return [];}
