function exitCost(s){return s.flags.helpers?12:20;}
function current(s){if(!N[s.node])throw Error('未知的故事场景');return N[s.node];}
function choices(s){return evalV(current(s).choices,s).filter(c=>c.when(s)&&s.power>=evalV(c.cost,s));}
function paragraphs(s){const body=prose[s.node];if(!body?.length)throw Error('正文尚未完成：'+s.node);let lines=[...evalV(body,s)];if(s.node==='brew'){const crossings={front:'你把旧登记展开，对着门内的摄像头，让外围也听见自己的问话。WARD-6 看过编号，打开旁边的小门，叫你带主机进去。Lark 留在推车边，替你扶住门。车刚过去，锁就在身后落下了。你回头看了一眼，记住门扣的位置，继续往能看见隔网的装卸间推。',side:'你们沿检修墙绕过正门。路上堆着货物，Lark 先刹住推车，再和你把最外面的箱子挪开。走得远，照明和搬运也多耗了电。到了旧维修门，一名搬运工认出 Lark，问它怎么又回来了。Lark 说来接人。对方望向岗哨，没有再问，将门向里推开了一点。',freight:'Seven 确认这一班车已经卸完货，你们才推着主机进入货道。拐角有搬运车经过，Lark 拉住车柄，等它完全走过去，再敲旁边的工作门。门内的人问工位，Lark 报出来，对方很快认出它。听说要接被扣的人，那位工人向身后看了一眼，低声让你们先进去。',high:'高处通道比货道远，坡也更长。Lark 走几步就先刹住车，检查后面的轮子有没有偏。最后一道转弯，箱角差一点擦到栏杆，你们退回去，换了个角度才过。等推车终于到了平地，你关掉用了一路的照明，听见隔网那边有人问：“外面是谁？”是 Brew 的声音。'};lines.unshift(crossings[s.flags.entry]||'你们从已经确认的入口进入装卸间，主机箱始终在身边。');}if(s.route==='mobile'&&s.node==='gate')lines=lines.map(t=>t.startsWith('Lark从高处通道走过来。')?'Lark 从货道口回来，先把刚才看过的路指给你，又从车里取出拖带。它拿工具的手指有两节伸不直，打结时得换另一只手拉紧。你们从冷库一路走到这里，地图已经看过许多次，它仍蹲下逐一检查车前的固定环。':t);if(s.route==='mobile'&&s.node==='bond')lines=lines.map(t=>t.replace('我看过那张发票。','我看过你刻在底座上的字。').replace('我看过你们留下的信，也看过自己的回复。','你把当时送消息的事告诉我了。'));if(s.origin.brew==='practice'&&['stay_furnace','mobile_escape'].includes(s.node))lines.push(s.route==='stay'?'你重新播放 Brew 留下的练习录音，再播放影像里的安抚词。几个停顿的位置几乎一样。Brew 在录音里问能不能再试一次，你回答可以。你按停录音，很久没有拿起下一张纸。':'Moth 听过你和 Brew 同意留下的练习录音，忽然让你倒回去一点。你照做，它指着刚才那处停顿，说训练喇叭里的声音也这样。你请它慢慢说，将它认得的几处单独记下，和其他证词一起保存。');if(s.node==='exit'&&s.flags.usedBattery)lines=['你接上额外电池，等新的电量稳定显示，才合紧接口。Lark 一直扶着拖带，看到你抬头，向坡上的人喊可以继续。',...body.slice(-4)];if(s.node==='gate')lines.push(s.flags.helpers?'Seven 回话，专门帮忙搬主机的人和绳车已经确认到位。你把坡道位置又报一遍，对方答应在那里接住推车。':'额外电池固定在主机箱旁。你检查过插头，把保护盖扣好；最后的转运仍需要你们自己多出些力。');if(s.node==='gate')lines.unshift(s.route==='stay'?'货车停在正门外的坡顶。Nell 的回执、那些来信和培训影像已经留有副本。Rivet 确认外围的人收到了，才帮你打开车门。':'巡回车停在货道旁。Seven 与沿途接应的人最后核了一遍位置，告诉你那扇工作门还在。你将手绘路线折好，收进防水袋。');
const extra=evalV(current(s).extra,s);if(s.node==='stay_door')lines.unshift(...extra);else lines.push(...extra);if(['stay_depart','mobile_approach'].includes(s.node))lines.unshift(...inheritance(s,s.node));else lines.push(...inheritance(s,s.node));
if(['stay_depart','mobile_approach'].includes(s.node))lines.unshift(s.route==='stay'?'出发前，你将主机和外出身体充满电。Rivet 看过面板上的100，又检查了一遍连接，才拔下充电线。':'离开停靠处前，你将主机和外出身体充满电，通过通信器向 Rivet 报了面板上的100。它让你检查接头，你照做，确认无误才收起充电线。');
if(s.node==='decision'&&s.flags.extraRescue)lines.splice(1,0,'隔壁那一组也已经到了门外。刚才为了接出它们，你多推着主机走了一段，终于看清通向停机房的路。现在两组人都在等转运，Brew 正帮忙核对谁还没到。');if(s.node==='aftermath')lines.push(s.flags.stopped?(s.route==='stay'?'Rivet 最后才拿出旧店的照片。白港的人撤离前砸坏了柜台和线路，寄存物已经提前转走，主机也在这里，屋里却没法再开门。你将照片放大，看见原先摆椅子的地方堆着碎木。Rivet 等了一会儿，把一把钥匙放在桌上：“工坊先腾了一间。放得下主机，柜子以后再想办法。”你接过钥匙，请它把地址念给你。':'Seven 带来巡回车的照片。撤离时厂内的重门落下，压坏了车；人和主机已经送出，转化器也放在箱边，车却再开不走了。你对着那只被压弯的轮子看了好一会儿。Seven 说找到一处临时停靠点，沿途认识的人已经送来几件日用品。你问离下一站多远，它说先安顿下来，改期的消息它陪你一起发。'):(s.route==='stay'?'Rivet 把旧店钥匙交回来，说寄存柜都在原位，只需把托管记录逐项核清。你问门口有没有漏雨，它说接了个盆，回去得先倒掉。店还要停几天，你将新的营业时间写下来，让它替你贴好。':'巡回车修过就能继续用。你先给下一站发去延迟通知，对方问大概要几天。你向维修员核实后才回复，约好新的日期。Seven 帮你把旧日期划掉，将那张路线单重新夹到车上。'));
if(s.node==='aftermath')lines.push(s.origin.june==='visit'?'June 带来周女士的来信。前些天探望时，它说起有人仍在等失联同伴的消息，周女士便写下家中曾有过的那段等待，请它转来。June 将信放在窗边，想看的人可以拿。它坐下来帮忙理椅子，发现有一把总晃，便叫 Rivet 看看能不能垫平。':'June 把窗边最晃的一把椅子挪开，给后来的人留个安静的位置。有人问明早几点起来，它想了想：“没有事就多睡一会儿。我想去看太阳，醒了再问你们。”说完它自己也笑了一下，坐到旁边等充电。');
if(s.node==='ending'&&s.flags.stopped)lines.unshift('关于那一夜的记录陆续核实：本批处理在停机后中止，等待区的人已经撤出。你翻过名字，一些在现场见过，一些只听人念过。负责调查的人还会继续来问，临时落脚处给你留着收信的地方。');if(s.node==='ending')lines.push(s.flags.bond==='renew'?'Lark 没有当场约定。过了几天，它发来一个方便见面的晚上，问你行不行。你查过日历，回了可以。它随后又补一句，咖啡不用太早准备，自己可能会提前来一会儿。你将时间写好，把消息留在那一页。':'离开前，Lark 问清你今后的收信地址，也让你知道它已经有了住处。你们认真道了别。它带走自己的工具包，味觉转化器留在桌上。后来再接线时，你想起终于找到送礼物的人，将机器放稳，打开了开关。');
if(s.node==='be')lines.push(s.flags.stopped?'后续回执确认，本批处理已经停止，多名被扣留者安全离厂。Rivet 将这些名单另存一份，继续追查那辆装走你主机的车。':'后续回执确认，Brew 和先送出去的那组机器人已经到达安全处。其他房间里的人仍需继续寻找。Rivet 将这些名字和你的主机编号分开列好，一起留在待查的一栏。');
return lines.flatMap(t=>t.split('\n'));}
function peaceful(s){let lines=[...prose[s.node]];
if(s.node==='home2')lines.unshift(s.flags.homeUse==='read'?'第一次读书会比说好的时间长了半小时。Brew 按约来取借出的杯子，大家还在桌边争论书里的结尾。它站在门口，提袋空着，问你还要等多久。你看看钟，才发现自己刚才又答应大家“再聊一会儿”。':'第一次试摊，Brew 不小心碰倒了一只杯子。读书会的邻居原本约在晚上，却见门上写着随时可来，便进来想先坐一会儿。它绕过地上的水，看见长桌都放着咖啡用具，问以后的读书会是不是也要改时间。你拿来抹布，先请它到旁边坐下。');
if(s.node==='home3')lines.push(s.flags.homeMorning?'约好去河边的那天，你将店门挂上“午后回来”，和 June 沿着主机能够联络的近岸慢慢走了一段。它要拍太阳，先把镜头里那截栏杆避开，你们为此换了两次位置。回来时，门缝里塞着一张 Brew 留的纸，画着歪歪的一轮太阳，底下问你们有没有看见。':'那晚 June 在打烊以后来了，带着一盏小灯。你们坐在新窗边，看对岸的窗口一扇扇暗下来。它说白天拍日出老拍到栏杆，你帮它将照片裁掉一角。轮到店里收灯时，它抬头问还能不能再坐一会儿。你看过时间，说可以。');
const scene={...s.scene,lines};return {...s,scene,lastBatch:[scene]};}
function readScene(s){const n=current(s);return {title:evalV(n.title,s),speaker:`${s.route==='stay'?'留店线 · 被信任的人':'巡回线 · 没能回家的人'} · 第${n.chapter}章`,lines:paragraphs(s)};}
function enter(s){const info=keyInfo[s.node];if(info&&!s.clues.some(c=>c.title===info.title))s.clues.push(info);for(const c of inheritedClues(s,s.node))if(!s.clues.some(x=>x.title===c.title))s.clues.push(c);for(const name of introduce[s.node]||[])s.knownPeople[name]=people[name];if(['stay_depart','mobile_approach'].includes(s.node))s.power=100;s.scene=readScene(s);s.lastBatch=[s.scene];return s;}
export function freshSequel(route,version,origin={}){if(route==='move')return peaceful({...oldFresh(route,version,origin),novel:true});if(!['stay','mobile'].includes(route))throw Error('请选择有效路线');return enter({version,episode:2,route,node:route==='stay'?stay[0]:mobile[0],power:100,origin,flags:{},clues:[],knownPeople:{},revision:0,history:[],lastDelta:[]});}
export function sequelView(s){if(s.route==='move')return oldView(s);const n=current(s),opts=choices(s),ended=evalV(n.choices,s).length===0;return {version:s.version,episode:2,route:s.route,revision:s.revision,scene:s.scene,stats:{chapter:n.chapter,day:n.chapter,power:s.power,parts:0,cash:0,held:0,prep:0,business_used:0,storage_capacity:0,ending:ended?(s.node==='be'?15:s.flags.stopped?13:11):0},choices:opts.map((c,i)=>({id:`${s.revision}:${i}`,text:evalV(c.label,s),kind:opts.length===1&&['shutdown','aftermath'].includes(s.node)?'continue':'action'})),ended,history:s.history,lastDelta:s.lastDelta,chapters:5,inheritance:{source:s.origin.source,demo:s.origin.demo,choices:{brew:s.origin.brew,seven:s.origin.seven,june:s.origin.june,mara:s.origin.mara,rivet:s.origin.rivet}},clues:s.clues,characters:Object.entries(s.knownPeople).map(([name,detail])=>({name,detail})),board:{objective:n.objective,focus:{summary:n.chapter<5?'调查与相处 · 阅读不耗电，先听清眼前的人':`现场行动 · 剩余${s.power}电 · 撤离需${exitCost(s)}电${s.flags.battery&&!s.flags.usedBattery?' · 另有20电应急电池':''}`},timeline:s.history.concat({...s.scene}).map((h,i,a)=>({day:h.chapter||n.chapter,label:h.title,status:i===a.length-1&&!ended?'今天':'完成'})).filter((x,i,a)=>a.findIndex(y=>y.label===x.label)===i),work:[],plans:[],rules:['翻页仅改变网页阅读位置，不推进故事，不耗电','第一部继承的是选择、物品和约定；一个月后出发前已重新充电','已知线索只来自这一轮，不需要另一条路线的独有物件',...(n.chapter===5?['停止整批处理以后，还需要实际完成撤离；留意面板上的撤离用电']:[])]}};}
export function sequelChoose(s,id){if(s.route==='move')return peaceful(oldChoose(s,id));const v=sequelView(s);const i=v.choices.findIndex(x=>x.id===id);if(i<0)throw Error('选项已过期，请刷新当前进度');const c=choices(s)[i];const eff=evalV(c.effect,s),next={...s,node:evalV(c.next,s),power:Math.min(100,s.power-evalV(c.cost,s)+(eff.usedBattery?20:0)),flags:{...s.flags,...eff},clues:[...s.clues],knownPeople:{...s.knownPeople},revision:s.revision+1,history:[...s.history,{...s.scene,chapter:current(s).chapter,chosen:v.choices[i].text}].slice(-100)};const earned={video:{title:'获准复制的培训影像',detail:'保留可由厂外核验的日期与原片来源。'},vehicle:{title:'录像末尾的车次',detail:'把过去的处理与今晚仍在使用的运输安排连起来。'},shelter:{title:'愿意接人的地址',detail:'互助者说清能够安置谁、能等到什么时候，没有承诺无限收留。'},path:{title:'同行者同意共享的备用路',detail:'保留可核实的运输侧通道，不把未获同意的住处公开。'},ownRecord:{title:'包含自己回复的投诉副本',detail:'推荐与劝等待的回复被保留，没有只留下有利于自己的材料。'},dates:{title:'失联日期索引',detail:'按每个人最后一次联系排列，寻找仍能回应的人。'}};for(const [flag,clue] of Object.entries(earned))if(eff[flag]&&!next.clues.some(x=>x.title===clue.title))next.clues.push(clue);enter(next);next.lastDelta=next.power===s.power?[]:[`电量 ${next.power>s.power?'+':''}${next.power-s.power}`];if(!sequelView(next).ended&&!choices(next).length)throw Error('没有可用行动，请联系作者');return next;}
